function validate(input) {
  const [{ students = [] }] = input;
  const ids = new Set();
  for (const [id] of students) {
    if (id === null) return 'Every student needs a student_id.';
    if (ids.has(id)) return `student_id ${id} appears twice in students.`;
    ids.add(id);
  }
  return null;
}

