function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['Ulysses', 'William', 'Henry', 'Mia', 'Omar', 'Lena', 'Kai'];
  const students = [];
  if (size === 'small') {
    // Ids near 101 (and 101 itself) so that off-by-one filters and wrong comparisons show up.
    const ids = [101, 53, 128, 3, 100, 102, 1, 10, 110, 1010, 11];
    for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
    const count = Math.floor(rand() * 9);
    for (let i = 0; i < count; i++) students.push([ids[i], pick(names), 5 + Math.floor(rand() * 15)]);
  } else {
    // 2,000 distinct ids in scrambled order; id 101 is present about half the time.
    const offset = Math.floor(rand() * 4001);
    for (let i = 0; i < 2000; i++) students.push([1 + (i * 1601 + offset) % 4001, pick(names), 5 + Math.floor(rand() * 15)]);
  }
  return [{ students }];
}
